<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>انتخاب صندلی | سینماپلاس</title><link rel="stylesheet" href="/css/cinema.css"></head><body class="booking-shell"><header class="booking-nav"><a class="brand" href="/">سینما<span class="brand-accent">پلاس</span></a><div class="steps"><b>۱ انتخاب صندلی</b><span>۲ اطلاعات و پرداخت</span><span>۳ تأیید نهایی</span></div><a class="back-link" href="{{ route('events.show',$show->event) }}">بازگشت ←</a></header><main class="booking-page"><div class="booking-header"><div><span class="eyebrow">سینما، بیش از یک تماشا</span><h1>{{ $show->event->title }}</h1><p>{{ $show->venue->name }} · {{ jdate($show->starts_at)->format('Y/m/d') }} · ساعت {{ $show->starts_at->format('H:i') }}</p></div><div class="poster-mini" style="background-image:url('{{ $show->event->getMedia('poster')->last()?->getUrl() ?: '/images/concepts/seat-selection-concept.png' }}')"></div></div><div class="booking-layout"><section class="seat-stage"><div class="screen">پرده نمایش</div><form method="post" action="{{ route('booking.checkout',$show) }}" id="seat-form">@csrf<div class="seat-map">@foreach($seats->groupBy('row_label') as $row=>$rowSeats)<div class="seat-row"><label>{{ $row }}</label>@foreach($rowSeats as $seat)<label class="seat {{ $seat->type==='vip'?'vip':'' }} {{ $taken->contains($seat->id)?'taken':'' }}"><input type="checkbox" name="seats[]" value="{{ $seat->id }}" {{ $taken->contains($seat->id)?'disabled':'' }} data-price="{{ $seat->type==='vip'&&$show->vip_price?$show->vip_price:$show->price }}"><span>{{ $seat->number }}</span></label>@endforeach</div>@endforeach</div><div class="legend"><span><i class="free"></i>آزاد</span><span><i class="selected"></i>انتخاب‌شده</span><span><i class="taken-dot"></i>رزروشده</span><span><i class="vip-dot"></i>VIP</span></div></form></section><aside class="summary"><div class="timer">زمان باقی‌مانده <strong>۰۴:۵۹</strong></div><h2>صندلی‌های انتخاب‌شده</h2><div id="selected-list" class="selected-seats muted">هنوز صندلی انتخاب نشده</div><hr><div class="total"><span>مبلغ قابل پرداخت</span><strong id="total">۰ تومان</strong></div><button class="primary full" form="seat-form" type="submit">ادامه پرداخت 🔒</button><small>پرداخت امن و مطمئن با رمزگذاری بانکی</small></aside></div></main><script>const checks=[...document.querySelectorAll('input[type=checkbox]')],total=document.querySelector('#total'),list=document.querySelector('#selected-list');function update(){let on=checks.filter(x=>x.checked),sum=on.reduce((a,x)=>a+Number(x.dataset.price),0);total.textContent=new Intl.NumberFormat('fa-IR').format(sum)+' تومان';list.innerHTML=on.length?on.map(x=>'<div>صندلی '+x.value+' <b>'+new Intl.NumberFormat('fa-IR').format(x.dataset.price)+' تومان</b></div>').join(''):'هنوز صندلی انتخاب نشده'}checks.forEach(x=>x.addEventListener('change',update));</script></body></html>
